// Integer-only digit classifier (8x8 images, 64 -> 32 ReLU -> 10), model in
// ml_model.h (generated by ml/train.py). RV32I has no multiply instruction,
// so products use a shift-and-add loop over the small unsigned activation.
//
// Two modes, chosen by the MMIO_IMAGE register:
//   0..N_TEST-1   classify that one test image, report class + logit
//                 checksum through MMIO (used by the fault-injection harness)
//   anything else classify all test images, check every result bit-exactly
//                 against the Python reference, print accuracy
//
// Hardened build (make PROG=digits OUT=digits_hard DEFS="-DBIAS16 -DMODEL_CHECK"):
//   BIAS16       biases stored as int16 instead of int32 (same values)
//   MODEL_CHECK  verify a checksum of all weights and biases before
//                classifying; on mismatch, report through MMIO_FAULT and stop
#include "mmio.h"
#ifdef BIAS16
#define BIAS_T int16_t
#endif
#include "ml_model.h"

// x * w for small unsigned x (input pixel 0..16 or hidden unit 0..127)
static inline int32_t mul_small(uint32_t x, int32_t w) {
    int32_t r = 0;
    while (x) {
        if (x & 1) r += w;
        w <<= 1;
        x >>= 1;
    }
    return r;
}

static int classify(const uint8_t *x, int32_t *out) {
    uint8_t h[N_HID];
    for (int j = 0; j < N_HID; j++) {
        int32_t acc = b1[j];
        for (int i = 0; i < N_IN; i++)
            if (x[i]) acc += mul_small(x[i], W1[i * N_HID + j]);
        acc >>= SHIFT1;
        h[j] = acc < 0 ? 0 : acc > 127 ? 127 : (uint8_t)acc;
    }
    int best = 0;
    for (int k = 0; k < N_OUT; k++) {
        int32_t acc = b2[k];
        for (int j = 0; j < N_HID; j++)
            if (h[j]) acc += mul_small(h[j], W2[j * N_OUT + k]);
        out[k] = acc;
        if (acc > out[best]) best = k;
    }
    return best;
}

static uint32_t checksum(const int32_t *out) {      // same as ml/train.py
    uint32_t s = 0;
    for (int k = 0; k < N_OUT; k++) s = ((s << 5) | (s >> 27)) ^ (uint32_t)out[k];
    return s;
}

#ifdef MODEL_CHECK
// same as model_sum() in ml/train.py; every array is word-aligned and a
// whole number of words long
static uint32_t sum_words(uint32_t s, const void *p, uint32_t bytes) {
    const uint32_t *w = (const uint32_t *)p;
    // Hide the pointer from the optimizer. The arrays are compile-time
    // constants, so without this clang computes the small ones' part of the
    // checksum at compile time (the bias words became instruction
    // immediates) and the check never reads that memory.
    __asm__ volatile("" : "+r"(w));
    for (uint32_t i = 0; i < bytes / 4; i++) s = ((s << 5) | (s >> 27)) ^ w[i];
    return s;
}

static int model_ok(void) {
    uint32_t s = sum_words(0, W1, sizeof W1);
    s = sum_words(s, b1, sizeof b1);
    s = sum_words(s, W2, sizeof W2);
    s = sum_words(s, b2, sizeof b2);
    return s == MODEL_SUM;
}
#endif

int main(void) {
    int32_t out[N_OUT];
    uint32_t idx = MMIO_IMAGE;

#ifdef MODEL_CHECK
    if (!model_ok()) {                               // corrupted model: fail-stop
        MMIO_FAULT = FAULT_MAGIC;
        puts_("model checksum mismatch\r\n");
        return 3;
    }
#endif

    if (idx < N_TEST) {                              // one image (fault trials)
        int c = classify(&test_x[idx * N_IN], out);
        MMIO_RESULT = c;
        MMIO_CHECK  = checksum(out);
        return 0;
    }

    puts_("digits: int8 MLP 64-32-10 on RV32I\r\n");
    int correct = 0, mismatches = 0;
    uint32_t c0 = MMIO_CYCLES;
    for (int n = 0; n < N_TEST; n++) {
        int c = classify(&test_x[n * N_IN], out);
        if (c == test_y[n]) correct++;
        if (c != test_pred[n] || checksum(out) != test_sum[n]) {
            mismatches++;
            puts_("  mismatch on image "); print_uint(n); puts_("\r\n");
        }
    }
    uint32_t cyc = MMIO_CYCLES - c0;
    puts_("accuracy "); print_uint(correct); puts_("/"); print_uint(N_TEST);
    puts_("  bit-exact vs Python: ");
    puts_(mismatches ? "NO" : "yes"); puts_("\r\n");
    puts_("cycles per image "); print_uint(cyc / N_TEST); puts_("\r\n");
    return mismatches;
}
